def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    rich_pressure = 0
    desperate_pressure = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
            if opp.get('budget', 0) >= 700:
                rich_pressure += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_pressure += 1

    if not alive:
        return float(min(budget, 8.0))

    high_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    # Estimate how tight the day is for 13-unit demand agents
    units_for_me = supply / float(WATER_REQ)
    very_tight = units_for_me < 1.35
    tight = units_for_me < 1.55
    loose = units_for_me > 1.75

    emergency = hp <= 2 or no_water >= 2
    urgent = hp <= 4 or no_water >= 1

    if emergency:
        bid = max(62.0, min(96.0, high_prev * 0.72 + 8.0))
        return float(min(budget, bid))

    if urgent and very_tight:
        bid = max(52.0, min(82.0, avg_prev * 0.5 + 10.0))
        return float(min(budget, bid))

    if loose:
        bid = 6.0
        if hp <= 5:
            bid = 12.0
        return float(min(budget, bid))

    if tight:
        bid = 18.0
        if rich_pressure >= 2:
            bid = 14.0
        if desperate_pressure >= 2:
            bid = 24.0
        if hp <= 6:
            bid += 8.0
        return float(min(budget, bid))

    bid = 10.0
    if hp <= 5:
        bid = 18.0
    if high_prev < 20.0 and avg_prev < 15.0:
        bid += 6.0

    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opps = []
    for k, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((k, o))

    # If no opponents alive, bid conservatively
    if not alive_opps:
        return max(0.0, min(float(my_status['budget']), DAILY_SALARY * 0.4))

    # Read yesterday bids (immediate reaction)
    yesterday_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Supply pressure: less supply => more aggressive bidding to secure WATER_REQ
    # Map supply in [15,25] to pressure in [1.0,0.6]
    if MAX_SUPPLY == MIN_SUPPLY:
        pressure = 1.0
    else:
        pressure = 1.0 - 0.4 * ((supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY))
        if pressure < 0.6:
            pressure = 0.6
        if pressure > 1.0:
            pressure = 1.0

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status.get('no_water_days', 0))

    # Critical HP: bid to avoid death
    if hp <= 2 or no_water_days >= 2:
        # Avoid overpaying; target near (but not equal to) their highest bids
        target = 0.85 * highest_prev_bid if highest_prev_bid > 0 else DAILY_SALARY * 0.9
        # Also scale by pressure
        target *= pressure
        bid = min(budget, max(DAILY_SALARY * 0.7, target))
        return max(0.0, bid)

    # Non-critical: bid moderately; if others were very high, slightly shadow them
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # They likely expect competition; bid enough to win when supply is tight
        bid = DAILY_SALARY * 0.55 * pressure
        # If their highest is far above, don't fully match; cap below their peak
        if highest_prev_bid > 0:
            bid = min(bid, highest_prev_bid * 0.75)
    else:
        # Their bids are moderate; we can be cheaper
        bid = DAILY_SALARY * 0.45 * pressure

    # Ensure we don't exceed budget
    bid = min(budget, bid)

    # Small day-based adjustment to avoid ties late (10-day episode)
    # Later days: slightly more aggressive
    if day >= 7:
        bid *= 1.08

    # Final clamp
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], 1.0)

    # In this scenario, supply (15-25) and WATER_REQ (13) means only one player
    # can get their full water requirement (int(supply / 13) is always 1).
    # This implies a winner-take-all situation for getting 13 water.

    base_bid = DAILY_SALARY * 0.95

    current_day = day_context['day']
    remaining_days = EPISODE_DAYS - current_day

    if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
        base_bid = DAILY_SALARY * 1.1
    elif my_status['hp'] <= 4:
        base_bid = DAILY_SALARY * 1.05
    elif remaining_days <= 2:
        base_bid = DAILY_SALARY * 1.1
    elif my_status['hp'] > 6 and my_status['budget'] > DAILY_SALARY * 3:
        base_bid = DAILY_SALARY * 0.85

    highest_opponent_prev_bid = 0.0
    for opp_id, opp_data in opponents_status.items():
        if opp_data['alive']:
            prev = opp_data.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                highest_opponent_prev_bid = max(highest_opponent_prev_bid, prev['bid'])

    competitive_bid = base_bid
    if highest_opponent_prev_bid > 0:
        competitive_bid = max(competitive_bid, highest_opponent_prev_bid + 2.0)

    competitive_bid = max(competitive_bid, DAILY_SALARY * 0.7)

    final_bid = min(my_status['budget'], competitive_bid)

    if current_day == EPISODE_DAYS:
        final_bid = my_status['budget']

    return max(0.0, final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15
    supply = day_context['supply']
    day = day_context['day']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    no_water_days = my_status['no_water_days']
    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.4)
    prev_bids = []
    for opp_id, opp in alive_opponents.items():
        prev_trace = opp.get('previous_trace', None)
        if prev_trace and prev_trace.get('bid') is not None:
            prev_bids.append(prev_trace['bid'])
    if my_hp <= 2:
        aggressive_bid = min(my_budget, DAILY_SALARY * 0.95)
        return aggressive_bid
    if prev_bids:
        avg_prev_bid = sum(prev_bids) / len(prev_bids)
        if avg_prev_bid >= DAILY_SALARY * 0.85:
            return min(my_budget, DAILY_SALARY * 0.4)
        else:
            bid = max(DAILY_SALARY * 0.5, avg_prev_bid + 1.5)
            return min(my_budget, bid)
    else:
        return min(my_budget, DAILY_SALARY * 0.55)
